import { useState } from "react";

function App() {
  const [text, setText] = useState("");
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleExtract = async () => {
    if (!text) return;

    setLoading(true);

    try {
      const response = await fetch("http://127.0.0.1:8000/extract", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          job_description: text,
        }),
      });

      const data = await response.json();
      setResult(data);
    } catch (error) {
      console.error(error);
    }

    setLoading(false);
  };

  const isLimited = result?.skills?.includes("LIMIT REACHED");

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 text-white p-6">

      <div className="max-w-5xl mx-auto">

        {/* NAVBAR */}
        <div className="flex justify-between items-center mb-8 border-b border-slate-700 pb-4">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center font-bold">
              JS
            </div>
            <span className="font-semibold text-lg">JobSkills</span>
          </div>

          <button
            onClick={() => window.open("https://your-payment-link.com", "_blank")}
            className="px-4 py-2 bg-green-500 hover:bg-green-600 rounded-lg text-sm font-medium"
          >
            Upgrade
          </button>
        </div>

        {/* HERO */}
        <h1 className="text-4xl font-bold text-center mb-2">
          Understand Any Job in Seconds
        </h1>

        <p className="text-gray-400 text-center mb-8">
          Paste a job description and instantly see required skills, level, and what you're missing.
        </p>

        {/* CARD */}
        <div className="bg-slate-800/70 backdrop-blur-xl rounded-2xl shadow-2xl p-8 border border-slate-700">

          <textarea
            className="w-full h-40 p-4 rounded-xl bg-slate-900 border border-slate-700 focus:outline-none focus:ring-2 focus:ring-indigo-500 mb-4"
            placeholder="Paste job description here..."
            value={text}
            onChange={(e) => setText(e.target.value)}
          />

          <button
            onClick={handleExtract}
            className="w-full py-3 rounded-xl bg-indigo-600 hover:bg-indigo-700 transition font-semibold shadow-lg shadow-indigo-500/20"
          >
            {loading ? "Analyzing..." : "Extract Skills"}
          </button>

          {result && (
            <div className="mt-8 space-y-6">

              <Card title="Core Skills" items={result.core_skills} highlight />

              <Card title="All Skills" items={result.skills} />

              <div>
                <h2 className="text-xl font-semibold mb-2">Missing Skills</h2>

                {isLimited ? (
                  <div className="bg-slate-900 border border-slate-700 p-6 rounded-xl text-center">
                    <p className="text-gray-400 mb-4">
                      🔒 Unlock missing skills and learning roadmap
                    </p>
                    <button
                      onClick={() =>
                        window.open("https://your-payment-link.com", "_blank")
                      }
                      className="px-6 py-2 bg-green-500 hover:bg-green-600 rounded-lg font-semibold"
                    >
                      Upgrade to Pro
                    </button>
                  </div>
                ) : (
                  <Card items={result.missing_skills} />
                )}
              </div>

              <div>
                <h2 className="text-xl font-semibold">Level</h2>
                <p className="text-indigo-400 font-medium">{result.level}</p>
              </div>

            </div>
          )}
        </div>
      </div>
    </div>
  );
}

function Card({ title, items = [], highlight }) {
  return (
    <div>
      {title && <h2 className="text-xl font-semibold mb-2">{title}</h2>}
      <div className="flex flex-wrap gap-2">
        {(items || []).map((item, index) => (
          <span
            key={index}
            className={`px-3 py-1 rounded-full text-sm ${
              highlight
                ? "bg-indigo-500 text-white"
                : "bg-slate-700 text-gray-200"
            }`}
          >
            {item}
          </span>
        ))}
      </div>
    </div>
  );
}

export default App;
